WITH base AS (SELECT * FROM departments WHERE dept_name = 'HR'), departments_stats AS (SELECT CASE WHEN budget >= 4151000 THEN 'high' WHEN budget >= 1899000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, ROUND(AVG(budget), 2) AS avg_budget FROM base GROUP BY CASE WHEN budget >= 4151000 THEN 'high' WHEN budget >= 1899000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, chiang_mai_count FROM departments_stats ORDER BY budget_bucket LIMIT 50;
